-- Rollback: UPDATE agent_issues SET description = substr(description, 1, instr(description, char(10) || char(10) || 'SESSION-RESEARCH-ERRATA-NOTES 2026-10-26') - 1) WHERE id IN (100449, 1000019, 100456, 1000002, 1000094) AND instr(description, 'SESSION-RESEARCH-ERRATA-NOTES 2026-10-26') > 0
--
-- ERRATA-ISSUE-NOTES-1 (2026-10-26, charter pillar research; agent_issues 100449, 1000019, 100456, 1000002, 1000094).
-- Five open issues about the errata chain carry a root cause that stopped being true (the head-of-line order and the 100 percent defer of
-- 2026-10-21 to 24), and a doer that trusts them would build a fix for a defect that no longer reproduces. This file appends what a live
-- read of 2026-10-26 17:50-18:50Z shows, as a dated note. It changes no status, no priority and no probe: the issues stay open because
-- their definitions of done (no internal-open row older than 24 h, content_items_over_stage_sla 0, the chain below 10 waiting) are not met.
-- The note is appended once (the marker stops a second run).

UPDATE agent_issues SET description = description || char(10) || char(10) || 'SESSION-RESEARCH-ERRATA-NOTES 2026-10-26 (read live 17:50-18:50Z, supersedes the root cause above): the head-of-line defect no longer reproduces. confirmInternalErrata selects ORDER BY RANDOM() LIMIT errata_confirm_max (qnfo-research-exec 0.34.0 and later), 9-12 rows settle every hour (all by deepseek-v4-flash-0731 since 05:00 UTC, kimi 0-1 an hour), errata_confirm_defer events are 2 in 24 h and 0 in the last 2 h (v_breach_selfheal_inputs.errata_defers_2h). The backlog (errata_queue internal-open 554, oldest 162 h) is rate-bound, not stuck: PAPER-LEARN-1 reads 8 papers an hour (the ceiling) and files up to 2 errata each, 12-14 an hour, against errata_confirm_max 12 an hour, which BREACH-SELFHEAL-1 holds at 12 because research neurons spent today (414,499) exceed research_daily_neurons (360,000); errata-hub spent 104,823 of those and qnfo-paper-reviser 20,112. Raising the confirm rate spends the budget the research stages need (publish_rate_ratio_24h 0.219). Residual hazard, not reproduced: a defer writes no durable state (errata_queue.confirm_attempts exists, every row 0, nothing writes it), so a row both models cannot read stays internal-open and is picked again at random; add the attempt count and a reasoned terminal status only if errata_confirm_defer rises above a few an hour. CONTENT-PIPELINE-SLA-1 (migrations/2026-10-26-content-pipeline-sla-attribution.sql) is the other change of the day on this chain.'
WHERE id IN (100449, 1000019) AND instr(COALESCE(description, ''), 'SESSION-RESEARCH-ERRATA-NOTES 2026-10-26') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'SESSION-RESEARCH-ERRATA-NOTES 2026-10-26 (read live 17:50-18:50Z): the three loops in the table above are not independent defects and two of the numbers were not stalls. (1) errata: the 882 (448 internal-errata + 434 errata rows on 2026-10-21) counted each erratum twice (internal_errata and its errata_queue row); the queue row is one waiting item, and its wait is the confirm rate (12 an hour) and the respond rate (5 an hour, ORDER BY id ASC LIMIT 5). (2) revision: of the 610 revision rows over SLA today, 454 are finished paper_revision_log outcomes (claim-corrected, claim-withdrawn, integrity-restored, claim-retracted, thin-prior-work-rejected and -skipped) that the view listed as waiting for ever; they are done or rejected since CONTENT-PIPELINE-SLA-1. loop-revision-queued (131) is real: revision_loop_mode has been off since 2026-10-25. (3) research queued: 192 of 192 rows in status queued were remediation rows, 174 of them errata rewrites that claimNew never claims (RB-ERRATA-SHARE-1 and CLAIM-ERRATA-SHARE-1 own that), and the daily neuron budget (COST-SUSTAIN-1, 360,000) was spent by 04:32 UTC, so every stage is held for the rest of the UTC day (224 research-budget events in 24 h, 8 papers published against a 36.6 a day base). content_items_over_stage_sla read 2500 at 18:30Z and 1179 at 18:44Z after the migration; the remaining items are real waiting items.'
WHERE id = 100456 AND instr(COALESCE(description, ''), 'SESSION-RESEARCH-ERRATA-NOTES 2026-10-26') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'SESSION-RESEARCH-ERRATA-NOTES 2026-10-26 (read live 17:50-18:50Z): the chain has a producer and a consumer at every step, and the audit line "errata_actions has no writer" is the fleet graph missing an edge: the respond member of qnfo-research-exec writes it (errata_actions: 238 routed high, 30 drafted high, 2 old low rows; 5 drafted and 5 routed an hour). What limits it is the rate at each step and the budget behind the last one: sweep 14 an hour -> confirm 12 an hour (errata_confirm_max, held by BREACH-SELFHEAL-1 while the budget is spent) -> respond 5 an hour -> route 5 an hour (routeHighRiskErrata, one research row per erratum, now one per paper in the data and, once ERRATA-ROUTE-PER-PAPER-1 lands, in the code) -> a research row the daily neuron budget can pay for about 8 times a day. Every draft has been risk high since 2026-10-02 (no ERRATA-JUDGE-1 gemma-4 call appears in ai_call_counters for errata-hub since 2026-10-23), so errata-publish never publishes one and each erratum becomes a research row. The chain is backpressured by design at the end, not wired wrong; do not retire it from the chain registry (item 3 of issue 1000002). Closing the pending count needs throughput or less inflow (PAPER-LEARN-1 findings per paper), an owner decision about the budget, not a repoint.'
WHERE id IN (1000002, 1000094) AND instr(COALESCE(description, ''), 'SESSION-RESEARCH-ERRATA-NOTES 2026-10-26') = 0;
